     + '<td>' + (pl.pods!=null ? fmt(pl.pods,0)
                 : (m.sql_engine==='X' ? '<span class="nd">—</span>' : '<span class="nd">팀 공통</span>')) + '</td>'
     + '<td>' + fmt(pl.guar,0) + '</td>'
     + '<td>' + fmt(lq[q],2) + '</td>'
     + '<td>' + (lim[q]==null ? '<span class="nd">—</span>' : fmt(lim[q],2)) + '</td>'
     + '<td>' + (lu[q]==null ? '<span class="nd">관측 없음</span>' : fmt(lu[q],2)) + '</td>'
     + '<td>' + (pend[q]==null ? '<span class="nd">—</span>' : fmt(pend[q],2)) + '</td>'
     + '<td>' + (apps[q]==null ? '<span class="nd">—</span>' : fmt(apps[q],0)) + '</td>'
     + '<td>' + (SHARED_Q[q]
         ? (s3shared==null ? '<span class="nd">관측 없음</span>'
            : fmt(s3shared/1073741824,1)+'<span class="nd"> 팀공통</span>')
         : (s3[q]==null ? '<span class="nd">관측 없음</span>' : fmt(s3[q]/1073741824,1))) + '</td>'
     + cell(cr, tc) + cell(mr, tc)
     + '<td><span class="chip ' + st[0] + '">' + st[1] + '</span></td></tr>';
});
h += '</tbody></table>';
h += SRC_LEGEND;
h += '<div class="ft">이 패널은 <b>레코딩 룰을 참조하지 않는다.</b> 대신 (a) 쿼터·사용량·대기·앱을 '
   + '<code>yunikorn_queue_resource</code>/<code>yunikorn_queue_app</code> 에서 매번 인라인으로 계산하고, '
   + '(b) 서비스 메타데이터와 배분표 계획값을 <b>패널 JS 에 하드코딩</b>했다. 값은 룰 버전과 동일하다.<br>'
   + 'state — <b>보장</b> guaranteed · <b>한계</b> max(버스트 상한) · <b>사용</b> allocated · '
   + '<b>대기</b> pending(자원 부족으로 못 뜬 요구) · <b>앱</b> yunikorn_queue_app{state="running"} · '
   + '<b>S3</b> minio_cluster_usage_buckets_total_bytes(ic-* 버킷을 서비스로 합산). '
   + '<span class="nd">—</span> 는 0 이 아니라 <b>시리즈 자체가 없음</b>(미관측).</div>';
H.registerHelper('svc', () => new H.SafeString(h));

